+package com.example.contact;
+
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps every message sent since the application started, so that the list
+ * survives leaving and coming back to the contact view. Nothing is stored on disk.
+ */
+@Service
+public class ContactService {
+
+    private final List<ContactMessage> sent = new CopyOnWriteArrayList<>();
+
+    public void send(ContactMessage message) {
+        sent.add(0, message);
+    }
+
+    /** Snapshot of all sent messages, newest first. */
+    public List<ContactMessage> sentMessages() {
+        return List.copyOf(sent);
+    }
+}
