+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.example.about.AboutView;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+    private static final Pattern EMAIL_ADDRESS = Pattern.compile("[^\\s@]+@[^\\s@]+\\.[^\\s@]+");
+
+    private final ContactService contactService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", e -> sendMessage());
+    private final Grid<ContactMessage> sentMessages = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog discardDialog = new Dialog();
+    /** True while the view clears its own fields, so that clearing them does not count as an edit. */
+    private boolean clearing;
+    /** A navigation postponed by {@link #beforeLeave}, waiting for the answer in the dialog. */
+    private ContinueNavigationAction pendingLeave;
+
+    public ContactView(ContactService contactService) {
+        this.contactService = contactService;
+
+        // The server decides what is invalid, and only when Send is pressed.
+        name.setManualValidation(true);
+        email.setManualValidation(true);
+        phone.setManualValidation(true);
+        message.setManualValidation(true);
+
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        name.addValueChangeListener(e -> fieldEdited());
+        email.addValueChangeListener(e -> fieldEdited());
+        phone.addValueChangeListener(e -> fieldEdited());
+        message.addValueChangeListener(e -> fieldEdited());
+
+        send.addThemeVariants(ButtonVariant.PRIMARY);
+
+        // Enter sends from any field. Shift+Enter still gives a new line in the message.
+        var form = new VerticalLayout(new FormLayout(name, email, phone, message), send);
+        Shortcuts.addShortcutListener(form, () -> {
+            if (send.isEnabled()) {
+                sendMessage();
+            }
+        }, Key.ENTER);
+
+        sentMessages.addColumn(ContactMessage::name).setHeader("Name");
+        sentMessages.addColumn(ContactMessage::email).setHeader("Email");
+        sentMessages.addColumn(ContactMessage::phone).setHeader("Phone");
+        sentMessages.addColumn(ContactMessage::message).setHeader("Message");
+        sentMessages.setItems(contactService.sentMessages());
+        sentMessages.setWidthFull();
+
+        discardDialog.setHeaderTitle("Discard your message?");
+        discardDialog.add(new Paragraph("Your message has not been sent. If you leave now, it is lost."));
+        discardDialog.getFooter().add(
+                new Button("Keep editing", e -> keepEditing()),
+                new Button("Discard", e -> discardAndLeave()));
+        // Closing the dialog with Esc or a click outside keeps the user here, just like "Keep editing".
+        discardDialog.addOpenedChangeListener(e -> {
+            if (!e.isOpened()) {
+                cancelPendingLeave();
+            }
+        });
+
+        setSizeFull();
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, sentMessages, discardDialog);
+        expand(sentMessages);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+        cancelPendingLeave();
+        pendingLeave = event.postpone();
+        discardDialog.open();
+    }
+
+    private void sendMessage() {
+        if (!validate()) {
+            return;
+        }
+        contactService.send(new ContactMessage(
+                name.getValue().strip(),
+                email.getValue().strip(),
+                phone.getValue().strip(),
+                message.getValue()));
+        sentMessages.setItems(contactService.sentMessages());
+        Notification.show("Message sent");
+
+        clearing = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearing = false;
+        send.setEnabled(false);
+        name.focus();
+    }
+
+    /** Marks every field that breaks a rule and returns whether the form is valid. */
+    private boolean validate() {
+        var nameError = name.getValue().isBlank() ? "Name is required" : null;
+        var emailError = emailError();
+        var messageError = messageError();
+
+        name.setInvalid(nameError != null);
+        name.setErrorMessage(nameError);
+        email.setInvalid(emailError != null);
+        email.setErrorMessage(emailError);
+        message.setInvalid(messageError != null);
+        message.setErrorMessage(messageError);
+
+        return nameError == null && emailError == null && messageError == null;
+    }
+
+    private String emailError() {
+        var address = email.getValue().strip();
+        if (!address.isEmpty()) {
+            return EMAIL_ADDRESS.matcher(address).matches() ? null : "Enter a valid e-mail address";
+        }
+        return phone.getValue().isBlank() ? "Give an e-mail address or a phone number" : null;
+    }
+
+    private String messageError() {
+        var text = message.getValue();
+        if (text.isBlank()) {
+            return "Message is required";
+        }
+        if (text.codePointCount(0, text.length()) > MAX_MESSAGE_LENGTH) {
+            return "Message must be at most " + MAX_MESSAGE_LENGTH + " characters";
+        }
+        return null;
+    }
+
+    private void fieldEdited() {
+        if (!clearing) {
+            send.setEnabled(true);
+        }
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void keepEditing() {
+        cancelPendingLeave();
+        discardDialog.close();
+    }
+
+    private void discardAndLeave() {
+        var leave = pendingLeave;
+        pendingLeave = null;
+        discardDialog.close();
+        leave.proceed();
+    }
+
+    /** Resolves a postponed navigation as cancelled, so the client router keeps working. */
+    private void cancelPendingLeave() {
+        if (pendingLeave != null) {
+            pendingLeave.cancel();
+            pendingLeave = null;
+        }
+    }
+}
